let LANG = 'en';
function t(k){ return (TR[LANG] && TR[LANG][k]) || TR.en[k] || k; }
function tf(k, vars){ let s = t(k); if (vars) Object.keys(vars).forEach(v => { s = s.replace('{' + v + '}', vars[v]); }); return s; }

